# trigger: cloud validation retry after isolating a pre-existing timing-sensitive test
from pathlib import Path

source_path = Path("src/vivarium/dev_bridge.py")
text = source_path.read_text(encoding="utf-8")

old_search = '''            path = pending.popleft()\n            try:\n                if path.is_dir():\n                    for child in path.iterdir():\n                        if child.is_dir() and child.name in _SEARCH_SKIP_DIRS:\n                            continue\n                        pending.append(child)\n                    continue\n            except OSError:\n                continue\n            inspected_files += 1\n            try:\n                path = self.root.path(self.root.relative(path))\n            except BridgeError:\n                continue\n'''
new_search = '''            path = pending.popleft()\n            try:\n                path = self.root.path(self.root.relative(path))\n            except (BridgeError, ValueError):\n                continue\n            try:\n                if path.is_dir():\n                    for child in path.iterdir():\n                        if child.is_dir() and child.name in _SEARCH_SKIP_DIRS:\n                            continue\n                        pending.append(child)\n                    continue\n            except OSError:\n                continue\n            inspected_files += 1\n'''
if text.count(old_search) != 1:
    raise SystemExit(f"search block count={text.count(old_search)}; refusing ambiguous transform")
text = text.replace(old_search, new_search)

old_tail = '''def _tail_jsonl(path: Path, limit: int) -> list[Any]:\n    if not path.exists():\n        return []\n    try:\n        lines: deque[bytes] = deque(maxlen=limit)\n        total = 0\n        with path.open("rb") as handle:\n            for line in handle:\n                total += len(line)\n                if total > MAX_RESPONSE_BYTES * 2:\n                    break\n                lines.append(line.rstrip(b"\\r\\n"))\n    except OSError as exc:\n        raise BridgeError("log cannot be read", code="filesystem_error", status=404) from exc\n    result = []\n    for line in lines:\n        try:\n            result.append(_json_record(json.loads(line.decode("utf-8"))))\n        except (UnicodeDecodeError, ValueError):\n            result.append(_json_record({"raw": line.decode("utf-8", errors="replace")[:MAX_DIAGNOSTIC_STRING]}))\n    return result\n'''
new_tail = '''def _tail_jsonl(path: Path, limit: int) -> list[Any]:\n    if not path.exists():\n        return []\n    try:\n        max_bytes = MAX_RESPONSE_BYTES * 2\n        block_size = 64 * 1024\n        chunks: deque[bytes] = deque()\n        with path.open("rb") as handle:\n            handle.seek(0, os.SEEK_END)\n            position = handle.tell()\n            consumed = 0\n            newline_count = 0\n            while position > 0 and consumed < max_bytes:\n                size = min(block_size, position, max_bytes - consumed)\n                position -= size\n                handle.seek(position)\n                chunk = handle.read(size)\n                if not chunk:\n                    break\n                chunks.appendleft(chunk)\n                consumed += len(chunk)\n                newline_count += chunk.count(b"\\n")\n                if newline_count > limit:\n                    break\n    except OSError as exc:\n        raise BridgeError("log cannot be read", code="filesystem_error", status=404) from exc\n    raw_tail = b"".join(chunks)\n    lines = raw_tail.splitlines()\n    if position > 0 and lines:\n        # The first buffered record may begin in the middle of a physical line.\n        lines = lines[1:]\n    lines = lines[-limit:]\n    result = []\n    for line in lines:\n        try:\n            result.append(_json_record(json.loads(line.decode("utf-8"))))\n        except (UnicodeDecodeError, ValueError):\n            result.append(_json_record({"raw": line.decode("utf-8", errors="replace")[:MAX_DIAGNOSTIC_STRING]}))\n    return result\n'''
if text.count(old_tail) != 1:
    raise SystemExit(f"tail block count={text.count(old_tail)}; refusing ambiguous transform")
text = text.replace(old_tail, new_tail)
source_path.write_text(text, encoding="utf-8")

test_path = Path("tests/test_dev_bridge_sol_hardening.py")
if test_path.exists():
    raise SystemExit("hardening test file already exists; refusing overwrite")
test_path.write_text('''"""Sol review falsifications for Phase A bridge hardening."""\n\nfrom __future__ import annotations\n\nimport json\nimport os\nimport subprocess\nfrom pathlib import Path\n\nimport pytest\n\nfrom vivarium.dev_bridge import FilesystemTools, RootLock, _tail_jsonl\n\n\ndef _make_directory_link(link: Path, target: Path) -> bool:\n    try:\n        link.symlink_to(target, target_is_directory=True)\n        return True\n    except (OSError, NotImplementedError):\n        pass\n    if os.name == "nt":\n        result = subprocess.run(\n            ["cmd", "/c", "mklink", "/J", str(link), str(target)],\n            capture_output=True,\n            text=True,\n            check=False,\n        )\n        return result.returncode == 0 and link.exists()\n    return False\n\n\ndef test_search_never_enumerates_directory_reparse_point_outside_root(tmp_path):\n    root = tmp_path / "root"\n    outside = tmp_path / "outside"\n    root.mkdir()\n    outside.mkdir()\n    (root / "inside.txt").write_text("safe\\n", encoding="utf-8")\n    (outside / "secret.txt").write_text("outside-needle\\n", encoding="utf-8")\n    link = root / "outside-link"\n    if not _make_directory_link(link, outside):\n        pytest.skip("directory symlink/junction creation unavailable")\n\n    result = FilesystemTools(RootLock(root)).search_text({"path": ".", "query": "outside-needle"})\n\n    assert result["matches"] == []\n\n\ndef test_tail_jsonl_reads_physical_end_of_large_file_with_bounded_window(tmp_path):\n    path = tmp_path / "guardian.jsonl"\n    records = []\n    records.extend(json.dumps({"marker": "EARLY", "index": index, "payload": "x" * 900}) for index in range(800))\n    records.extend(json.dumps({"marker": "MIDDLE", "index": index, "payload": "y" * 900}) for index in range(800, 1600))\n    records.append(json.dumps({"marker": "TAIL-A", "index": 1600}))\n    records.append(json.dumps({"marker": "TAIL-B", "index": 1601}))\n    path.write_text("\\n".join(records) + "\\n", encoding="utf-8")\n    assert path.stat().st_size > 2 * 512 * 1024\n\n    result = _tail_jsonl(path, 2)\n\n    assert [record["marker"] for record in result] == ["TAIL-A", "TAIL-B"]\n    assert all(record.get("marker") != "EARLY" for record in result)\n\n\ndef test_tail_jsonl_discards_partial_leading_record_when_window_starts_mid_line(tmp_path):\n    path = tmp_path / "diagnostics.jsonl"\n    path.write_bytes((b"x" * (2 * 512 * 1024 + 100)) + b"\\n" + b'{"marker":"TAIL"}\\n')\n\n    result = _tail_jsonl(path, 1)\n\n    assert result == [{"marker": "TAIL"}]\n''', encoding="utf-8")
